1	// Seeded random number generator (mulberry32). Same seed -> same run,
2	// which makes baseline comparisons fair and bugs reproducible.
3	export class Rng {
4	  private s: number;
5	  constructor(seed: number) {
6	    this.s = seed >>> 0 || 1;
7	  }
8	  next(): number {
9	    let t = (this.s = (this.s + 0x6d2b79f5) >>> 0);
10	    t = Math.imul(t ^ (t >>> 15), t | 1);
11	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
12	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
13	  }
14	  range(a: number, b: number): number {
15	    return a + (b - a) * this.next();
16	  }
17	  int(n: number): number {
18	    return Math.floor(this.next() * n);
19	  }
20	  normal(): number {
21	    const u = Math.max(1e-12, this.next());
22	    const v = this.next();
23	    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
24	  }
25	}
