1	import { Rng } from "./rng";
2	
3	export enum Tile {
4	  Grass = 0,
5	  Forest = 1,
6	  Sand = 2,
7	  Rock = 3,
8	  Water = 4,
9	}
10	
11	export const TILE_NAMES = ["grass", "forest", "sand", "rock", "water"];
12	
13	// How readily each tile type catches fire (0 = never) and how long it burns.
14	export const FUEL: Record<Tile, { ignite: number; burnTicks: number }> = {
15	  [Tile.Grass]: { ignite: 1.0, burnTicks: 25 },
16	  [Tile.Forest]: { ignite: 0.85, burnTicks: 70 },
17	  [Tile.Sand]: { ignite: 0, burnTicks: 0 },
18	  [Tile.Rock]: { ignite: 0, burnTicks: 0 },
19	  [Tile.Water]: { ignite: 0, burnTicks: 0 },
20	};
21	
22	export interface Terrain {
23	  w: number;
24	  h: number;
25	  height: Float32Array; // absolute terrain height per tile
26	  type: Uint8Array; // Tile enum per tile
27	  village: number[]; // tile indices of the protected village
28	  base: { x: number; y: number };
29	}
30	
31	// Smooth value noise with several octaves -> rolling hills.
32	function makeNoise(rng: Rng, w: number, h: number, octaves: number): Float32Array {
33	  const out = new Float32Array(w * h);
34	  let amp = 1;
35	  let total = 0;
36	  for (let o = 0; o < octaves; o++) {
37	    const cell = Math.max(2, Math.floor(Math.min(w, h) / 2 ** (o + 1)));
38	    const gw = Math.ceil(w / cell) + 2;
39	    const gh = Math.ceil(h / cell) + 2;
40	    const grid = new Float32Array(gw * gh);
41	    for (let i = 0; i < grid.length; i++) grid[i] = rng.next();
42	    for (let y = 0; y < h; y++) {
43	      for (let x = 0; x < w; x++) {
44	        const gx = x / cell;
45	        const gy = y / cell;
46	        const x0 = Math.floor(gx);
47	        const y0 = Math.floor(gy);
48	        const fx = smooth(gx - x0);
49	        const fy = smooth(gy - y0);
50	        const a = grid[y0 * gw + x0];
51	        const b = grid[y0 * gw + x0 + 1];
52	        const c = grid[(y0 + 1) * gw + x0];
53	        const d = grid[(y0 + 1) * gw + x0 + 1];
54	        out[y * w + x] += amp * lerp(lerp(a, b, fx), lerp(c, d, fx), fy);
55	      }
56	    }
57	    total += amp;
58	    amp *= 0.5;
59	  }
60	  for (let i = 0; i < out.length; i++) out[i] /= total;
61	  return out;
62	}
63	
64	const smooth = (t: number) => t * t * (3 - 2 * t);
65	const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
66	
67	function percentile(arr: Float32Array, p: number): number {
68	  const s = Array.from(arr).sort((a, b) => a - b);
69	  return s[Math.floor(p * (s.length - 1))];
70	}
71	
72	export function generateTerrain(rng: Rng, w: number, h: number, heightScale: number): Terrain {
73	  const raw = makeNoise(rng, w, h, 4);
74	  const veg = makeNoise(rng, w, h, 3);
75	  const height = new Float32Array(w * h);
76	  const type = new Uint8Array(w * h);
77	
78	  const waterLevel = percentile(raw, 0.1);
79	  const rockLevel = percentile(raw, 0.93);
80	  const forestLevel = percentile(veg, 0.3); // ~70% coniferous forest
81	
82	  for (let i = 0; i < w * h; i++) {
83	    height[i] = raw[i] * heightScale;
84	    if (raw[i] <= waterLevel) type[i] = Tile.Water;
85	    else if (raw[i] >= rockLevel) type[i] = Tile.Rock;
86	    else type[i] = veg[i] > forestLevel ? Tile.Forest : Tile.Grass;
87	  }
88	  // Water surfaces are flat.
89	  for (let i = 0; i < w * h; i++) if (type[i] === Tile.Water) height[i] = waterLevel * heightScale;
90	
91	  // Sandy shores next to water.
92	  for (let y = 0; y < h; y++) {
93	    for (let x = 0; x < w; x++) {
94	      const i = y * w + x;
95	      if (type[i] === Tile.Water || type[i] === Tile.Rock) continue;
96	      if (raw[i] > waterLevel + 0.03) continue;
97	      if (neighbours4(x, y, w, h).some((j) => type[j] === Tile.Water)) type[i] = Tile.Sand;
98	    }
99	  }
100	
101	  // Guarantee at least two water sources: carve small ponds if the noise made none.
102	  let waterCount = 0;
103	  for (let i = 0; i < w * h; i++) if (type[i] === Tile.Water) waterCount++;
104	  if (waterCount < 20) {
105	    for (let p = 0; p < 2; p++) carvePond(rng, type, height, w, h, waterLevel * heightScale);
106	  }
107	
108	  // Village: a 3x3 cluster of grass near the lower-middle of the map.
109	  const village: number[] = [];
110	  const vc = findLand(type, w, h, Math.floor(w * 0.55), Math.floor(h * 0.72));
111	  for (let dy = -1; dy <= 1; dy++) {
112	    for (let dx = -1; dx <= 1; dx++) {
113	      const x = clamp(vc.x + dx, 0, w - 1);
114	      const y = clamp(vc.y + dy, 0, h - 1);
115	      const i = y * w + x;
116	      type[i] = Tile.Grass;
117	      village.push(i);
118	    }
119	  }
120	
121	  // Home base: bottom-left area on dry land, away from the village.
122	  const base = findLand(type, w, h, Math.floor(w * 0.12), Math.floor(h * 0.88));
123	
124	  return { w, h, height, type, village, base };
125	}
