127	function carvePond(rng: Rng, type: Uint8Array, height: Float32Array, w: number, h: number, level: number) {
128	  const cx = 5 + rng.int(w - 10);
129	  const cy = 5 + rng.int(h - 10);
130	  for (let y = cy - 2; y <= cy + 2; y++) {
131	    for (let x = cx - 2; x <= cx + 2; x++) {
132	      if ((x - cx) ** 2 + (y - cy) ** 2 > 5) continue;
133	      type[y * w + x] = Tile.Water;
134	      height[y * w + x] = Math.min(height[y * w + x], level);
135	    }
136	  }
137	}
138	
139	function findLand(type: Uint8Array, w: number, h: number, sx: number, sy: number) {
140	  // Spiral outwards from (sx, sy) until a flammable land tile is found.
141	  for (let r = 0; r < Math.max(w, h); r++) {
142	    for (let dy = -r; dy <= r; dy++) {
143	      for (let dx = -r; dx <= r; dx++) {
144	        const x = sx + dx;
145	        const y = sy + dy;
146	        if (x < 1 || y < 1 || x >= w - 1 || y >= h - 1) continue;
147	        const t = type[y * w + x];
148	        if (t === Tile.Grass || t === Tile.Forest) return { x, y };
149	      }
150	    }
151	  }
152	  return { x: sx, y: sy };
153	}
154	
155	export function neighbours4(x: number, y: number, w: number, h: number): number[] {
156	  const out: number[] = [];
157	  if (x > 0) out.push(y * w + x - 1);
158	  if (x < w - 1) out.push(y * w + x + 1);
159	  if (y > 0) out.push((y - 1) * w + x);
160	  if (y < h - 1) out.push((y + 1) * w + x);
161	  return out;
162	}
163	
164	export const clamp = (v: number, a: number, b: number) => (v < a ? a : v > b ? b : v);
