1	import { Environment, Fire } from "./environment";
2	
3	// A drone's (or the base's) private picture of the fire.
4	// Every tile stores what was believed AND when it was last seen, so maps from
5	// different drones can be merged tile-by-tile: the newest observation wins.
6	export class BeliefMap {
7	  fire: Uint8Array;
8	  severity: Float32Array;
9	  lastSeen: Int32Array; // tick of last observation, -1 = never seen
10	
11	  constructor(readonly w: number, readonly h: number) {
12	    const n = w * h;
13	    this.fire = new Uint8Array(n);
14	    this.severity = new Float32Array(n);
15	    this.lastSeen = new Int32Array(n).fill(-1);
16	  }
17	
18	  observe(i: number, env: Environment, tick: number) {
19	    this.fire[i] = env.fire[i];
20	    this.severity[i] = env.severity[i];
21	    this.lastSeen[i] = tick;
22	  }
23	
24	  // A full snapshot of the truth (initial briefing / satellite pass).
25	  observeAll(env: Environment, tick: number) {
26	    this.fire.set(env.fire);
27	    this.severity.set(env.severity);
28	    this.lastSeen.fill(tick);
29	  }
30	
31	  // Merge another map into this one, keeping the newer observation per tile.
32	  mergeFrom(o: BeliefMap) {
33	    const ls = this.lastSeen;
34	    const ols = o.lastSeen;
35	    for (let i = 0; i < ls.length; i++) {
36	      if (ols[i] > ls[i]) {
37	        ls[i] = ols[i];
38	        this.fire[i] = o.fire[i];
39	        this.severity[i] = o.severity[i];
40	      }
41	    }
42	  }
43	
44	  copyFrom(o: BeliefMap) {
45	    this.fire.set(o.fire);
46	    this.severity.set(o.severity);
47	    this.lastSeen.set(o.lastSeen);
48	  }
49	
50	  // When we extinguish a tile ourselves we know it is out, even before re-sensing.
51	  markExtinguished(i: number, tick: number) {
52	    this.fire[i] = Fire.Burnt;
53	    this.severity[i] = 0;
54	    this.lastSeen[i] = tick;
55	  }
56	
57	  anyFire(): boolean {
58	    for (let i = 0; i < this.fire.length; i++) if (this.fire[i] === Fire.Burning) return true;
59	    return false;
60	  }
61	}
62	
63	// Merge a group of maps so that every member ends up with the combined newest view.
64	// Used for drones (and the base) that can currently reach each other.
65	export function mergeGroup(maps: BeliefMap[]) {
66	  if (maps.length < 2) return;
67	  const [first, ...rest] = maps;
68	  for (const m of rest) first.mergeFrom(m);
69	  for (const m of rest) m.copyFrom(first);
70	}
