1	import { Config } from "./config";
2	import { Environment } from "./environment";
3	import { Terrain } from "./terrain";
4	
5	export interface Blackout {
6	  x: number;
7	  y: number;
8	  r: number;
9	}
10	
11	export interface CommsNode {
12	  id: number; // drones use their id; the base uses BASE_ID
13	  x: number;
14	  y: number;
15	  z: number; // absolute altitude
16	  range: number;
17	}
