19	export const BASE_ID = -1;
20	
21	// Height of the terrain at a fractional position (bilinear).
22	export function terrainHeightAt(t: Terrain, x: number, y: number) {
23	  const cx = Math.max(0, Math.min(t.w - 1.001, x));
24	  const cy = Math.max(0, Math.min(t.h - 1.001, y));
25	  const x0 = Math.floor(cx);
26	  const y0 = Math.floor(cy);
27	  const fx = cx - x0;
28	  const fy = cy - y0;
29	  const h = t.height;
30	  const w = t.w;
31	  const a = h[y0 * w + x0];
32	  const b = h[y0 * w + x0 + 1];
33	  const c = h[(y0 + 1) * w + x0];
34	  const d = h[(y0 + 1) * w + x0 + 1];
35	  return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy;
36	}
37	
38	export function inBlackout(blackouts: Blackout[], x: number, y: number) {
39	  for (const b of blackouts) if ((x - b.x) ** 2 + (y - b.y) ** 2 <= b.r * b.r) return true;
40	  return false;
41	}
42	
43	// Can a and b talk directly? Needs: in range, clear 3D line of sight over the hills,
44	// neither inside a blackout zone, and (optionally) no thick smoke in between.
45	export function canLink(
46	  a: CommsNode,
47	  b: CommsNode,
48	  terrain: Terrain,
49	  env: Environment,
50	  blackouts: Blackout[],
51	  cfg: Config,
52	): boolean {
53	  const dx = b.x - a.x;
54	  const dy = b.y - a.y;
55	  const dist = Math.hypot(dx, dy);
56	  if (dist > Math.min(a.range, b.range)) return false;
57	  if (inBlackout(blackouts, a.x, a.y) || inBlackout(blackouts, b.x, b.y)) return false;
58	  const steps = Math.max(2, Math.ceil(dist * 2));
59	  for (let s = 1; s < steps; s++) {
60	    const t = s / steps;
61	    const x = a.x + dx * t;
62	    const y = a.y + dy * t;
63	    const lineZ = a.z + (b.z - a.z) * t;
64	    if (terrainHeightAt(terrain, x, y) > lineZ) return false; // a hill is in the way
65	    if (cfg.smokeBlocksComms && env.smokeAt(x, y) > cfg.thickSmoke * 1.5) return false;
66	  }
67	  return true;
68	}
69	
70	export interface Network {
71	  links: [number, number][]; // pairs of node ids with a direct link
72	  componentOf: Map<number, number>; // node id -> component index
73	  components: number[][]; // node ids per component (relaying = multi-hop)
74	}
75	
76	export function buildNetwork(
77	  nodes: CommsNode[],
78	  terrain: Terrain,
79	  env: Environment,
80	  blackouts: Blackout[],
81	  cfg: Config,
82	): Network {
83	  const links: [number, number][] = [];
84	  const adj = new Map<number, number[]>();
85	  for (const n of nodes) adj.set(n.id, []);
86	  for (let i = 0; i < nodes.length; i++) {
87	    for (let j = i + 1; j < nodes.length; j++) {
88	      if (canLink(nodes[i], nodes[j], terrain, env, blackouts, cfg)) {
89	        links.push([nodes[i].id, nodes[j].id]);
90	        adj.get(nodes[i].id)!.push(nodes[j].id);
91	        adj.get(nodes[j].id)!.push(nodes[i].id);
92	      }
93	    }
94	  }
95	  // Connected components: messages can hop through intermediate drones.
96	  const componentOf = new Map<number, number>();
97	  const components: number[][] = [];
98	  for (const n of nodes) {
99	    if (componentOf.has(n.id)) continue;
100	    const comp: number[] = [];
101	    const stack = [n.id];
102	    componentOf.set(n.id, components.length);
103	    while (stack.length) {
104	      const id = stack.pop()!;
105	      comp.push(id);
106	      for (const m of adj.get(id)!) {
107	        if (!componentOf.has(m)) {
108	          componentOf.set(m, components.length);
109	          stack.push(m);
110	        }
111	      }
112	    }
113	    components.push(comp);
114	  }
115	  return { links, componentOf, components };
116	}
