6	// A task zone: one chunk of the believed fire front that drones can bid on.
7	export interface Zone {
8	  id: number;
9	  target: number; // tile index to drop water on (most threatening front tile)
10	  tx: number;
11	  ty: number;
12	  value: number; // threat score
13	  frontier: number; // number of front tiles in the zone
14	  slots: number; // how many drones the zone is worth
15	}
