17	// Threat of one burning tile on the front: how bad is it if nobody fights it?
18	export function tileThreat(
19	  i: number,
20	  belief: BeliefMap,
21	  terrain: Terrain,
22	  wind: Wind,
23	  villageX: number,
24	  villageY: number,
25	  unburntNeighbours: number,
26	): number {
27	  const w = terrain.w;
28	  const x = i % w;
29	  const y = Math.floor(i / w);
30	  const sev = Math.max(1, belief.severity[i]);
31	  const dx = villageX - x;
32	  const dy = villageY - y;
33	  const d = Math.hypot(dx, dy) + 1e-6;
34	  const proximity = 1 + 8 * Math.exp(-d / 10); // closer to the village = much worse
35	  const towards = (Math.cos(wind.angle) * dx + Math.sin(wind.angle) * dy) / d; // is the wind pushing it at the village?
36	  const windF = 1 + 2 * wind.speed * Math.max(0, towards);
37	  const fuelAhead = unburntNeighbours / 8; // fire with lots of fuel next to it will keep growing
38	  return sev * proximity * windF * (0.3 + fuelAhead);
39	}
