41	// Group the believed fire front into zones and score them.
42	export function computeZones(belief: BeliefMap, terrain: Terrain, wind: Wind, cfg: Config): Zone[] {
43	  const { w, h, type } = terrain;
44	  const v = terrain.village[4];
45	  const vx = v % w;
46	  const vy = Math.floor(v / w);
47	  const zs = cfg.zoneSize;
48	  const nbx = Math.ceil(w / zs);
49	  const zones = new Map<number, Zone>();
50	  let bestThreat = new Map<number, number>();
51	
52	  for (let y = 0; y < h; y++) {
53	    for (let x = 0; x < w; x++) {
54	      const i = y * w + x;
55	      if (belief.fire[i] !== Fire.Burning) continue;
56	      let unburnt = 0;
57	      for (let dy = -1; dy <= 1; dy++) {
58	        for (let dx = -1; dx <= 1; dx++) {
59	          if (!dx && !dy) continue;
60	          const nx = x + dx;
61	          const ny = y + dy;
62	          if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
63	          const j = ny * w + nx;
64	          if (belief.fire[j] === Fire.Unburnt && FUEL[type[j] as Tile].ignite > 0) unburnt++;
65	        }
66	      }
67	      if (unburnt === 0) continue; // interior of the fire: will burn out on its own
68	      const t = tileThreat(i, belief, terrain, wind, vx, vy, unburnt);
69	      const zid = Math.floor(y / zs) * nbx + Math.floor(x / zs);
70	      let z = zones.get(zid);
71	      if (!z) {
72	        z = { id: zid, target: i, tx: x, ty: y, value: 0, frontier: 0, slots: 1 };
73	        zones.set(zid, z);
74	        bestThreat.set(zid, -1);
75	      }
76	      z.value += t;
77	      z.frontier++;
78	      if (t > bestThreat.get(zid)!) {
79	        bestThreat.set(zid, t);
80	        z.target = i;
81	        z.tx = x;
82	        z.ty = y;
83	      }
84	    }
85	  }
86	  const out = [...zones.values()];
87	  for (const z of out) {
88	    z.slots = Math.max(1, Math.min(4, Math.ceil(z.frontier / 5)));
89	    if (z.frontier <= 3) z.value *= 1.5; // small spot fires can be fully put out: worth jumping on
90	  }
91	  return out;
92	}
