4	// Particle filter guessing where an out-of-contact teammate probably is.
5	// Each particle is one guess. They all start at the teammate's last known
6	// position and fly towards its last known target with random variation, so the
7	// cloud spreads the longer we go without hearing from it.
8	export class TeammateTracker {
9	  xs: Float32Array;
10	  ys: Float32Array;
11	  private basedOn = -1; // stamp of the claim the cloud was started from
12	
13	  constructor(readonly n: number) {
14	    this.xs = new Float32Array(n);
15	    this.ys = new Float32Array(n);
16	  }
17	
18	  reset(c: Claim) {
19	    this.xs.fill(c.x);
20	    this.ys.fill(c.y);
21	    this.basedOn = c.stamp;
22	  }
23	
24	  // Advance one tick. `claim` is the last thing we heard from the teammate.
25	  update(c: Claim, speed: number, rng: Rng) {
26	    if (this.basedOn !== c.stamp) this.reset(c);
27	    for (let k = 0; k < this.n; k++) {
28	      const dx = c.tx - this.xs[k];
29	      const dy = c.ty - this.ys[k];
30	      const d = Math.hypot(dx, dy);
31	      const s = speed * rng.range(0.5, 1.05);
32	      if (d > s) {
33	        this.xs[k] += (dx / d) * s + rng.normal() * 0.25;
34	        this.ys[k] += (dy / d) * s + rng.normal() * 0.25;
35	      } else {
36	        // Arrived (maybe): wander around the target as it works the fire / refills.
37	        this.xs[k] += rng.normal() * 0.6;
38	        this.ys[k] += rng.normal() * 0.6;
39	      }
40	    }
41	  }
42	
43	  // Fraction of guesses within `r` tiles of (x, y).
44	  fractionNear(x: number, y: number, r: number) {
45	    let c = 0;
46	    const r2 = r * r;
47	    for (let k = 0; k < this.n; k++) if ((this.xs[k] - x) ** 2 + (this.ys[k] - y) ** 2 <= r2) c++;
48	    return c / this.n;
49	  }
50	
51	  spread() {
52	    let mx = 0;
53	    let my = 0;
54	    for (let k = 0; k < this.n; k++) {
55	      mx += this.xs[k];
56	      my += this.ys[k];
57	    }
58	    mx /= this.n;
59	    my /= this.n;
60	    let v = 0;
61	    for (let k = 0; k < this.n; k++) v += (this.xs[k] - mx) ** 2 + (this.ys[k] - my) ** 2;
62	    return Math.sqrt(v / this.n);
63	  }
64	}
