9	export type DroneState =
10	  | "idle"
11	  | "toFire" // flying to its zone's target tile
12	  | "toWater" // flying to a water source to refill
13	  | "refilling"
14	  | "toBase" // returning to recharge / repair / get maps
15	  | "charging"
16	  | "scouting" // no known fire: checking areas not seen for a while
