19	export class Drone {
20	  x: number;
21	  y: number;
22	  state: DroneState = "idle";
23	  water: number;
24	  battery = 1; // drains over time, faster in headwind / climbing
25	  damage = 0; // builds up flying over fire and through smoke; 1 = destroyed
26	  belief: BeliefMap;
27	  claims = new Map<number, Claim>(); // what I know about every drone's current plan
28	  trackers = new Map<number, TeammateTracker>();
29	  zone = -1; // zone currently claimed
30	  targetX = 0;
31	  targetY = 0;
32	  targetTile = -1;
33	  lastZones: Zone[] = []; // for the UI: what this drone considered last time
34	  lastScores: { zone: number; score: number; taken: number }[] = [];
35	  waterDropped = 0;
36	  orders: { zone: number; tile: number } | null = null; // central mode only
37	  lostAt = -1;
38	  private visitedBaseForMaps = false;
39	
40	  constructor(readonly id: number, x: number, y: number, cfg: Config, w: number, h: number) {
41	    this.x = x;
42	    this.y = y;
43	    this.water = cfg.waterCapacity;
44	    this.belief = new BeliefMap(w, h);
45	  }
46	
47	  get alive() {
48	    return this.state !== "dead";
49	  }
50	
51	  altitude(t: Terrain, cfg: Config) {
52	    return terrainHeightAt(t, this.x, this.y) + cfg.droneAltitude;
53	  }
54	
55	  // Look at the tiles around me. Thick smoke shrinks how far I can see.
56	  sense(env: Environment, cfg: Config, tick: number) {
57	    let r = cfg.sensorRadius;
58	    if (cfg.smokeBlocksSensing) r = r / (1 + env.smokeAt(this.x, this.y) / cfg.thickSmoke);
59	    r = Math.max(1.5, r);
60	    const r2 = r * r;
61	    const x0 = Math.max(0, Math.floor(this.x - r));
62	    const x1 = Math.min(env.w - 1, Math.ceil(this.x + r));
63	    const y0 = Math.max(0, Math.floor(this.y - r));
64	    const y1 = Math.min(env.h - 1, Math.ceil(this.y + r));
65	    for (let y = y0; y <= y1; y++) {
66	      for (let x = x0; x <= x1; x++) {
67	        if ((x - this.x) ** 2 + (y - this.y) ** 2 <= r2) this.belief.observe(y * env.w + x, env, tick);
68	      }
69	    }
70	    return r;
71	  }
72	
73	  myClaim(tick: number, bid: number): Claim {
74	    return {
75	      droneId: this.id,
76	      zone: this.zone,
77	      bid,
78	      stamp: tick,
79	      x: this.x,
80	      y: this.y,
81	      tx: this.targetX,
82	      ty: this.targetY,
83	      water: this.water,
84	    };
85	  }
86	
87	  // Fly one tick towards (tx, ty). Returns true when arrived.
88	  moveTowards(tx: number, ty: number, env: Environment, cfg: Config): boolean {
89	    const dx = tx - this.x;
90	    const dy = ty - this.y;
91	    const d = Math.hypot(dx, dy);
92	    const terrain = env.terrain;
93	    const hBefore = terrainHeightAt(terrain, this.x, this.y);
94	    if (d <= cfg.droneSpeed) {
95	      this.x = tx;
96	      this.y = ty;
97	    } else {
98	      this.x += (dx / d) * cfg.droneSpeed;
99	      this.y += (dy / d) * cfg.droneSpeed;
100	    }
101	    const hAfter = terrainHeightAt(terrain, this.x, this.y);
102	    // Battery: base drain, more into a headwind, more when climbing.
103	    let drain = cfg.batteryDrain;
104	    if (d > 0) {
105	      const head = -(Math.cos(env.wind.angle) * dx + Math.sin(env.wind.angle) * dy) / d;
106	      drain *= 1 + 0.8 * env.wind.speed * Math.max(0, head);
107	    }
108	    drain += Math.max(0, hAfter - hBefore) * 0.0006;
109	    this.battery -= drain;
110	    return d <= cfg.droneSpeed;
111	  }
112	
113	  hover(env: Environment, cfg: Config) {
114	    this.battery -= cfg.batteryDrain * (1 + 0.4 * env.wind.speed);
115	  }
116	
117	  // Fire and smoke wear the drone down.
118	  takeDamage(env: Environment, cfg: Config) {
119	    const i = Math.round(this.y) * env.w + Math.round(this.x);
120	    if (env.fire[i] === 1) this.damage += cfg.fireDamage * Math.max(1, env.severity[i]);
121	    this.damage += cfg.smokeDamage * env.smokeAt(this.x, this.y);
122	  }
123	
124	  // Battery needed to fly back to base from here, with a safety margin.
125	  batteryToReturn(bx: number, by: number, cfg: Config) {
126	    const d = Math.hypot(bx - this.x, by - this.y);
127	    return (d / cfg.droneSpeed) * cfg.batteryDrain * 1.6 + 0.04;
128	  }
129	
130	  setVisitedBase(v: boolean) {
131	    this.visitedBaseForMaps = v;
132	  }
133	  get visitedBase() {
134	    return this.visitedBaseForMaps;
135	  }
136	}
