39	  constructor(cfg: Partial<Config> = {}) {
40	    this.cfg = { ...defaultConfig, ...cfg };
41	    const c = this.cfg;
42	    this.rng = new Rng(c.seed);
43	    this.agentRng = new Rng(c.seed * 7919 + 13);
