48	    for (let i = 0; i < this.terrain.type.length; i++) if (this.terrain.type[i] === Tile.Water) this.waterTiles.push(i);
49	
50	    const b = this.terrain.base;
51	    this.base = { x: b.x, y: b.y, belief: new BeliefMap(c.width, c.height), manualOutage: false };
52	    this.base.belief.observeAll(this.env, 0); // initial briefing (satellite / spotter plane)
53	    for (let k = 0; k < c.droneCount; k++) {
54	      const d = new Drone(k, b.x + this.agentRng.range(-1, 1), b.y + this.agentRng.range(-1, 1), c, c.width, c.height);
