142	    for (const comp of this.network.components) {
143	      const hasBase = comp.includes(BASE_ID);
144	      if (c.mode === "central" && !hasBase) continue; // central drones only talk via base
145	      const maps: BeliefMap[] = [];
146	      for (const id of comp) maps.push(id === BASE_ID ? this.base.belief : this.drones[id].belief);
147	      mergeGroup(maps);
148	
149	      if (c.mode === "swarm") {
150	        const members = comp.filter((id) => id !== BASE_ID).map((id) => this.drones[id]);
151	        // Heartbeat: each member republishes its plan with its current position.
152	        const merged = new Map<number, Claim>();
153	        for (const m of members) {
154	          for (const [id, cl] of m.claims) {
155	            const ex = merged.get(id);
156	            if (!ex || cl.stamp > ex.stamp) merged.set(id, cl);
157	          }
158	        }
159	        for (const m of members) {
160	          const prev = merged.get(m.id);
161	          merged.set(m.id, m.myClaim(this.tick, prev?.bid ?? 0));
162	        }
163	        for (const m of members) m.claims = new Map(merged);
164	      }
165	    }
166	  }
167	
168	  private publishClaim(d: Drone, claim: Claim) {
169	    d.claims.set(d.id, claim);
170	    const comp = this.network.componentOf.get(d.id);
171	    if (comp === undefined) return;
172	    for (const id of this.network.components[comp]) {
173	      if (id !== BASE_ID && id !== d.id) this.drones[id].claims.set(d.id, claim);
174	    }
175	  }
176	
177	  private updateTrackers() {
178	    const c = this.cfg;
179	    for (const d of this.drones) {
180	      if (!d.alive) continue;
181	      for (const [id, cl] of d.claims) {
182	        if (id === d.id) continue;
183	        if (this.tick - cl.stamp <= 1) {
184	          d.trackers.delete(id); // in contact: no need to guess
185	          continue;
186	        }
187	        let tr = d.trackers.get(id);
188	        if (!tr) {
189	          tr = new TeammateTracker(c.trackerParticles);
190	          tr.reset(cl);
191	          d.trackers.set(id, tr);
192	        }
193	        tr.update(cl, c.droneSpeed, this.agentRng);
194	      }
195	    }
196	  }
197	
198	  // ---------------------------------------------------------------- per-drone behaviour
199	  private act(d: Drone) {
200	    const c = this.cfg;
201	    const env = this.env;
202	    d.takeDamage(env, c);
203	    if (d.damage >= 1 || d.battery <= 0) {
204	      d.state = "dead";
205	      d.lostAt = this.tick;
206	      return;
207	    }
208	
209	    if (d.state === "charging") {
210	      d.battery = Math.min(1, d.battery + 0.03);
211	      d.damage = Math.max(0, d.damage - 0.03);
212	      // Docked: swap maps with base by cable, even if base radio is down.
213	      d.belief.mergeFrom(this.base.belief);
214	      this.base.belief.mergeFrom(d.belief);
215	      if (d.battery >= 1 && d.damage <= 0) {
216	        d.state = "idle";
217	        d.setVisitedBase(!d.belief.anyFire());
218	      }
219	      return;
220	    }
221	
222	    // Safety first: go home if battery or health is getting low.
223	    if (d.state !== "toBase" && (d.battery < d.batteryToReturn(this.base.x, this.base.y, c) || d.damage > 0.7)) {
224	      d.state = "toBase";
225	    }
226	    if (d.state === "toBase") {
227	      if (d.moveTowards(this.base.x, this.base.y, env, c)) d.state = "charging";
228	      return;
229	    }
230	
231	    if (d.state === "refilling") {
232	      d.water = Math.min(c.waterCapacity, d.water + 0.5);
233	      d.hover(env, c);
234	      if (d.water >= c.waterCapacity) d.state = "idle";
235	      return;
236	    }
237	    if (d.water <= 0 && d.state !== "toWater") {
238	      const wt = this.bestWaterTile(d.x, d.y, d.targetX, d.targetY);
239	      d.state = "toWater";
240	      d.targetTile = wt;
241	      d.targetX = wt % env.w;
242	      d.targetY = Math.floor(wt / env.w);
243	      if (c.mode === "swarm") this.publishClaim(d, d.myClaim(this.tick, d.claims.get(d.id)?.bid ?? 0));
244	    }
245	    if (d.state === "toWater") {
246	      if (d.moveTowards(d.targetX, d.targetY, env, c)) d.state = "refilling";
247	      return;
248	    }
249	
250	    // Has water: decide what to fight (periodically, or when the current job is done).
251	    const targetGone = d.targetTile >= 0 && d.state === "toFire" && d.belief.fire[d.targetTile] !== Fire.Burning;
252	    if (d.state === "idle" || targetGone || this.tick % c.decisionInterval === d.id % c.decisionInterval) {
253	      if (d.state !== "scouting" || d.belief.anyFire()) this.decide(d);
254	    }
255	
256	    if (d.state === "toFire") {
257	      if (d.moveTowards(d.targetX, d.targetY, env, c)) {
258	        env.dropWater(d.targetTile, 1);
259	        d.water -= 1;
260	        d.waterDropped++;
261	        d.sense(env, c, this.tick);
262	        d.state = "idle";
263	      }
264	    } else if (d.state === "scouting") {
265	      if (d.moveTowards(d.targetX, d.targetY, env, c)) d.state = "idle";
266	    } else {
267	      d.hover(env, c);
268	    }
269	  }
270	
271	  private decide(d: Drone) {
272	    const mode = this.cfg.mode;
273	    if (mode === "central") return this.decideCentral(d);
274	    const zones = this.zonesFor(d);
275	    d.lastZones = zones;
276	    if (zones.length === 0) return this.noKnownFire(d);
277	    d.setVisitedBase(false);
278	
279	    const c = this.cfg;
280	    const scored = zones.map((z) => {
281	      const raw = z.value / (this.timeToImpact(d, z) + 5);
282	      return { z, raw, score: raw * (z.id === d.zone ? c.stickiness : 1) };
283	    });
284	    scored.sort((a, b) => b.score - a.score);
285	
286	    let chosen = scored[0];
287	    d.lastScores = [];
288	    if (mode === "swarm") {
289	      // Consensus auction: skip zones that enough teammates (with better bids) already hold.
290	      // Out-of-contact teammates count as "probably there" in proportion to how
291	      // confident the particle filter is that they're still working that zone.
292	      let best: (typeof scored)[number] | null = null;
293	      let fallback = scored[0];
294	      let fallbackScore = -1;
295	      for (const s of scored) {
296	        let taken = 0;
297	        for (const [id, cl] of d.claims) {
298	          if (id === d.id || cl.zone !== s.z.id) continue;
299	          const age = this.tick - cl.stamp;
300	          if (age <= 1) {
301	            if (cl.bid > s.raw || (cl.bid === s.raw && id < d.id)) taken += 1;
302	          } else {
303	            const tr = d.trackers.get(id);
304	            const near = tr ? tr.fractionNear(s.z.tx, s.z.ty, c.zoneSize * 1.2) : 1;
305	            taken += Math.exp(-age / c.trackerTimescale) * near;
306	          }
307	        }
308	        if (d.lastScores.length < 5) d.lastScores.push({ zone: s.z.id, score: s.raw, taken });
309	        const adj = s.score / (1 + taken);
310	        if (adj > fallbackScore) {
311	          fallbackScore = adj;
312	          fallback = s;
313	        }
314	        if (taken < s.z.slots - 0.5) {
315	          best = s;
316	          break;
317	        }
318	      }
319	      chosen = best ?? fallback;
320	    } else {
321	      d.lastScores = scored.slice(0, 5).map((s) => ({ zone: s.z.id, score: s.raw, taken: 0 }));
322	    }
323	
324	    this.assign(d, chosen.z);
325	    if (mode === "swarm") this.publishClaim(d, d.myClaim(this.tick, chosen.raw));
326	  }
327	
328	  private assign(d: Drone, z: Zone) {
329	    d.zone = z.id;
330	    d.targetTile = z.target;
331	    d.targetX = z.tx;
332	    d.targetY = z.ty;
333	    d.state = "toFire";
334	  }
335	
336	  // No fire on my map: go home to fetch the base's map; if that has none either, scout.
337	  private noKnownFire(d: Drone) {
338	    d.zone = -1;
339	    if (!d.visitedBase) {
340	      d.state = "toBase";
341	      return;
342	    }
343	    // Scout: pick a spot that hasn't been looked at for a long time, not too far away.
344	    let best = -1;
345	    let bestScore = -Infinity;
346	    for (let k = 0; k < 40; k++) {
347	      const i = this.agentRng.int(this.env.w * this.env.h);
348	      const x = i % this.env.w;
349	      const y = Math.floor(i / this.env.w);
350	      const age = this.tick - Math.max(0, d.belief.lastSeen[i]);
351	      const s = age - 0.7 * Math.hypot(x - d.x, y - d.y);
352	      if (s > bestScore) {
353	        bestScore = s;
354	        best = i;
355	      }
356	    }
357	    d.targetTile = best;
358	    d.targetX = best % this.env.w;
359	    d.targetY = Math.floor(best / this.env.w);
360	    d.state = "scouting";
361	    if (this.cfg.mode === "swarm") this.publishClaim(d, d.myClaim(this.tick, 0));
362	  }
363	
364	  // ---------------------------------------------------------------- central baseline
365	  // Base assigns every drone it can reach. Drones out of contact keep their last
366	  // order and, once it's done, fly home for new orders.
367	  private centralAssign() {
368	    if (!this.baseOnline) return;
369	    const comp = this.network.componentOf.get(BASE_ID);
370	    if (comp === undefined) return;
371	    const reachable = this.network.components[comp].filter((id) => id !== BASE_ID).map((id) => this.drones[id]);
372	    const zones = computeZones(this.base.belief, this.terrain, this.env.wind, this.cfg);
373	    const pairs: { d: Drone; z: Zone; s: number }[] = [];
374	    for (const d of reachable) {
375	      if (!d.alive || d.water <= 0) continue;
376	      for (const z of zones) pairs.push({ d, z, s: z.value / (this.timeToImpact(d, z) + 5) });
377	    }
378	    pairs.sort((a, b) => b.s - a.s);
379	    const used = new Map<number, number>();
380	    const done = new Set<number>();
381	    // Pass 1: fill each zone up to its slots, best bids first.
382	    for (const p of pairs) {
383	      if (done.has(p.d.id)) continue;
384	      if ((used.get(p.z.id) ?? 0) >= p.z.slots) continue;
385	      used.set(p.z.id, (used.get(p.z.id) ?? 0) + 1);
386	      done.add(p.d.id);
387	      p.d.orders = { zone: p.z.id, tile: p.z.target };
388	    }
389	    // Pass 2: spare drones reinforce whichever zone gains most from one more drone.
390	    for (const d of reachable) {
391	      if (done.has(d.id) || !d.alive || d.water <= 0) continue;
392	      let best: Zone | null = null;
393	      let bs = -1;
394	      for (const z of zones) {
395	        const s = z.value / (this.timeToImpact(d, z) + 5) / (1 + (used.get(z.id) ?? 0));
396	        if (s > bs) {
397	          bs = s;
398	          best = z;
399	        }
400	      }
401	      if (best) {
402	        used.set(best.id, (used.get(best.id) ?? 0) + 1);
403	        done.add(d.id);
404	        d.orders = { zone: best.id, tile: best.target };
405	      }
406	    }
407	    for (const d of reachable) if (!done.has(d.id)) d.orders = null;
408	  }
409	
410	  private decideCentral(d: Drone) {
411	    const o = d.orders;
412	    if (o && d.belief.fire[o.tile] === Fire.Burning) {
413	      d.zone = o.zone;
414	      d.targetTile = o.tile;
415	      d.targetX = o.tile % this.env.w;
416	      d.targetY = Math.floor(o.tile / this.env.w);
417	      d.state = "toFire";
418	      return;
419	    }
420	    d.orders = null;
421	    d.zone = -1;
422	    // No valid orders: if base is reachable, wait for the next assignment; otherwise go home.
423	    if (this.inContact(d.id, BASE_ID)) d.state = "idle";
424	    else d.state = "toBase";
425	  }
426	
427	  // ---------------------------------------------------------------- helpers
428	  private zonesFor(d: Drone): Zone[] {
429	    // Drones that just merged maps share identical beliefs, but we compute per drone
430	    // anyway: each drone plans from its OWN map.
431	    return computeZones(d.belief, this.terrain, this.env.wind, this.cfg);
432	  }
433	
434	  timeToImpact(d: Drone, z: Zone) {
435	    const c = this.cfg;
436	    if (d.water > 0) return Math.hypot(z.tx - d.x, z.ty - d.y) / c.droneSpeed;
437	    const wt = this.bestWaterTile(d.x, d.y, z.tx, z.ty);
438	    const wx = wt % this.env.w;
439	    const wy = Math.floor(wt / this.env.w);
440	    return (Math.hypot(wx - d.x, wy - d.y) + Math.hypot(z.tx - wx, z.ty - wy)) / c.droneSpeed + c.waterCapacity / 0.5;
441	  }
442	
443	  // Water source that minimises the detour from (x, y) to (tx, ty).
444	  bestWaterTile(x: number, y: number, tx: number, ty: number) {
445	    let best = this.waterTiles[0];
446	    let bd = Infinity;
447	    const w = this.env.w;
448	    for (const i of this.waterTiles) {
449	      const wx = i % w;
450	      const wy = Math.floor(i / w);
451	      const dd = Math.hypot(wx - x, wy - y) + Math.hypot(tx - wx, ty - wy);
452	      if (dd < bd) {
453	        bd = dd;
454	        best = i;
455	      }
456	    }
457	    return best;
458	  }
459	
460	  // ---------------------------------------------------------------- judge controls
461	  igniteAt(x: number, y: number) {
462	    return this.env.ignite(this.env.idx(Math.round(x), Math.round(y)), 1);
463	  }
464	  addBlackout(x: number, y: number, r: number) {
465	    this.blackouts.push({ x, y, r });
466	  }
467	  clearBlackouts() {
468	    this.blackouts = [];
469	  }
470	  crashDrone(id: number) {
471	    const d = this.drones[id];
472	    if (d && d.alive) {
473	      d.state = "dead";
474	      d.lostAt = this.tick;
475	    }
476	  }
477	  setWind(angle: number, speed: number) {
478	    this.env.wind.angle = angle;
479	    this.env.wind.speed = speed;
480	  }
481	}
