120	function drawChart() {
121	  const c = $<HTMLCanvasElement>("chart");
122	  const ctx = c.getContext("2d")!;
123	  ctx.clearRect(0, 0, c.width, c.height);
124	  const hist = world.history;
125	  if (hist.length < 2) return;
126	  const maxV = Math.max(10, ...hist.map((h) => h.burnt));
127	  const maxT = Math.max(200, hist[hist.length - 1].tick);
128	  const line = (key: "burning" | "burnt", colour: string) => {
129	    ctx.strokeStyle = colour;
130	    ctx.lineWidth = 1.5;
131	    ctx.beginPath();
132	    hist.forEach((h, k) => {
133	      const x = (h.tick / maxT) * c.width;
134	      const y = c.height - 2 - (h[key] / maxV) * (c.height - 4);
135	      k ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
136	    });
137	    ctx.stroke();
138	  };
139	  line("burnt", "#9aa0a6");
140	  line("burning", "#ff9f1c");
141	  ctx.fillStyle = "#9aa0a6";
142	  ctx.font = "11px sans-serif";
143	  ctx.fillText("burning (orange) / burnt (grey)", 4, 12);
144	}
