164	      <span>Drone</span><b>#${d.id} — ${d.state}</b>
165	      <span>Battery</span><b>${Math.round(d.battery * 100)}%</b>
166	      <span>Damage</span><b>${Math.round(d.damage * 100)}%</b>
167	      <span>Water</span><b>${d.water.toFixed(1)} / ${world.cfg.waterCapacity}</b>
168	      <span>Can reach</span><b>${mates.length ? mates.join(", ") : "nobody"}</b>
169	      <span>Guessing</span><b>${lost.length ? lost.join(", ") : "—"}</b>
170	    </div>
171	    ${
172	      world.cfg.mode === "central"
173	        ? `<p class="hint">Central mode: follows base's orders (${d.orders ? "zone " + d.orders.zone : "none"}).</p>`
174	        : `<table><tr><th>Zone</th><th>Bid</th><th>Already taken by</th></tr>${rows}</table>
175	           <p class="hint">"Already taken" counts teammates with better bids, plus a probability for out-of-contact teammates the drone thinks are still there.</p>`
176	    }`;
177	}
178	
179	// ---------------------------------------------------------------- loop
180	let frame = 0;
181	function loop() {
182	  if (playing && !world.finished) {
183	    const steps = Number($<HTMLInputElement>("speed").value);
184	    for (let k = 0; k < steps; k++) world.step();
185	    if (world.cfg.windDrift && frame % 10 === 0) syncWindSliders();
186	  }
187	  renderer.draw(view);
188	  if (frame % 5 === 0) {
189	    updateStats();
190	    updateDroneInfo();
191	    $("rangeVal").textContent = String(world.cfg.commsRange);
192	  }
193	  frame++;
194	  requestAnimationFrame(loop);
195	}
196	
197	newRun();
198	loop();
