1	// Top-down renderer. Kept completely separate from the simulation so an
2	// isometric renderer can be dropped in later without touching src/sim.
3	import { BASE_ID } from "../sim/comms";
4	import { Drone } from "../sim/drone";
5	import { Fire } from "../sim/environment";
6	import { Tile } from "../sim/terrain";
7	import { World } from "../sim/world";
8	
9	export interface ViewOptions {
10	  beliefOf: number | null; // show this drone's belief instead of the truth
11	  selected: number | null;
12	  showLinks: boolean;
13	  showSmoke: boolean;
14	  showClouds: boolean;
15	  showSensors: boolean;
16	}
17	
18	const TILE_RGB: Record<number, [number, number, number]> = {
19	  [Tile.Grass]: [143, 191, 90],
20	  [Tile.Forest]: [47, 107, 58],
21	  [Tile.Sand]: [217, 200, 143],
22	  [Tile.Rock]: [138, 133, 128],
23	  [Tile.Water]: [63, 127, 191],
24	};
25	
26	const STATE_COLOUR: Record<string, string> = {
27	  idle: "#e0e0e0",
28	  toFire: "#ff9f1c",
29	  toWater: "#4cc9f0",
30	  refilling: "#4cc9f0",
31	  toBase: "#b388ff",
32	  charging: "#b388ff",
33	  scouting: "#80ed99",
34	  dead: "#555",
35	};
36	
37	const TEAM_COLOURS = ["#ff595e", "#ffca3a", "#8ac926", "#1982c4", "#6a4c93", "#f15bb5", "#00bbf9", "#fee440", "#9b5de5", "#00f5d4", "#fb5607", "#3a86ff"];
38	
39	export class Renderer {
40	  private terrainImg: HTMLCanvasElement;
41	  private overlay: HTMLCanvasElement;
42	  private smokeLayer: HTMLCanvasElement;
43	  readonly scale: number;
44	
45	  constructor(private canvas: HTMLCanvasElement, private world: World) {
46	    const { w, h } = world.terrain;
47	    this.scale = Math.floor(Math.min(canvas.width / w, canvas.height / h));
48	    this.terrainImg = this.buildTerrain();
49	    this.overlay = document.createElement("canvas");
50	    this.overlay.width = w;
51	    this.overlay.height = h;
52	    this.smokeLayer = document.createElement("canvas");
53	    this.smokeLayer.width = w;
54	    this.smokeLayer.height = h;
55	  }
56	
57	  // Terrain colours with simple hill shading, drawn once.
58	  private buildTerrain() {
59	    const { w, h, height, type } = this.world.terrain;
60	    const hs = this.world.cfg.heightScale;
61	    const c = document.createElement("canvas");
62	    c.width = w;
63	    c.height = h;
64	    const ctx = c.getContext("2d")!;
65	    const img = ctx.createImageData(w, h);
66	    for (let y = 0; y < h; y++) {
67	      for (let x = 0; x < w; x++) {
68	        const i = y * w + x;
69	        const [r, g, b] = TILE_RGB[type[i]];
70	        const west = height[y * w + Math.max(0, x - 1)];
71	        const north = height[Math.max(0, y - 1) * w + x];
72	        const shade = type[i] === Tile.Water ? 1 : 0.78 + (0.3 * height[i]) / hs + 0.06 * (height[i] - west + height[i] - north);
73	        img.data[i * 4] = r * shade;
74	        img.data[i * 4 + 1] = g * shade;
75	        img.data[i * 4 + 2] = b * shade;
76	        img.data[i * 4 + 3] = 255;
77	      }
78	    }
79	    ctx.putImageData(img, 0, 0);
80	    return c;
81	  }
82	
83	  draw(opts: ViewOptions) {
84	    const world = this.world;
85	    const { w, h } = world.terrain;
86	    const s = this.scale;
87	    const ctx = this.canvas.getContext("2d")!;
88	    ctx.imageSmoothingEnabled = false;
89	    ctx.fillStyle = "#111";
90	    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
91	    ctx.drawImage(this.terrainImg, 0, 0, w * s, h * s);
92	
93	    // Fire layer: the truth, or what one drone believes.
94	    const viewer = opts.beliefOf !== null ? world.drones[opts.beliefOf] : null;
95	    const fire = viewer ? viewer.belief.fire : world.env.fire;
96	    const sev = viewer ? viewer.belief.severity : world.env.severity;
97	    const octx = this.overlay.getContext("2d")!;
98	    const oimg = octx.createImageData(w, h);
99	    const maxSev = world.cfg.maxSeverity;
100	    for (let i = 0; i < w * h; i++) {
101	      const o = i * 4;
102	      if (fire[i] === Fire.Burning) {
103	        const t = Math.min(1, sev[i] / maxSev);
104	        oimg.data[o] = 255;
105	        oimg.data[o + 1] = 210 * (1 - t) + 30 * t;
106	        oimg.data[o + 2] = 40 * (1 - t);
107	        oimg.data[o + 3] = 235;
108	      } else if (fire[i] === Fire.Burnt) {
109	        oimg.data[o] = 43;
110	        oimg.data[o + 1] = 37;
111	        oimg.data[o + 2] = 35;
112	        oimg.data[o + 3] = 220;
113	      } else if (!viewer && world.env.wetness[i] > 0.05) {
114	        oimg.data[o] = 120;
115	        oimg.data[o + 1] = 190;
116	        oimg.data[o + 2] = 255;
117	        oimg.data[o + 3] = 120 * world.env.wetness[i];
118	      }
119	      if (viewer) {
120	        // Darken tiles this drone hasn't seen recently: its map is out of date there.
121	        const seen = viewer.belief.lastSeen[i];
122	        const age = seen < 0 ? 1e9 : world.tick - seen;
123	        const dark = Math.min(0.75, age / 300);
124	        if (oimg.data[o + 3] === 0) {
125	          oimg.data[o + 3] = 255 * dark;
126	        } else {
127	          oimg.data[o] *= 1 - dark;
128	          oimg.data[o + 1] *= 1 - dark;
129	          oimg.data[o + 2] *= 1 - dark;
130	        }
131	      }
132	    }
133	    octx.putImageData(oimg, 0, 0);
134	    ctx.drawImage(this.overlay, 0, 0, w * s, h * s);
135	
136	    // Village and base.
137	    for (const v of world.terrain.village) {
138	      const x = (v % w) * s;
139	      const y = Math.floor(v / w) * s;
140	      ctx.fillStyle = world.env.fire[v] === Fire.Unburnt ? "#f4e3c1" : "#5a3a2a";
141	      ctx.fillRect(x + s * 0.2, y + s * 0.4, s * 0.6, s * 0.5);
142	      ctx.fillStyle = "#b23a2a";
143	      ctx.beginPath();
144	      ctx.moveTo(x + s * 0.1, y + s * 0.45);
145	      ctx.lineTo(x + s * 0.5, y + s * 0.1);
146	      ctx.lineTo(x + s * 0.9, y + s * 0.45);
147	      ctx.fill();
148	    }
149	    const bx = (world.base.x + 0.5) * s;
150	    const by = (world.base.y + 0.5) * s;
151	    ctx.fillStyle = world.baseOnline ? "#ffffff" : "#777";
152	    ctx.beginPath();
153	    ctx.arc(bx, by, s * 1.2, 0, Math.PI * 2);
154	    ctx.fill();
155	    ctx.fillStyle = "#222";
156	    ctx.font = `bold ${Math.round(s * 1.4)}px sans-serif`;
157	    ctx.textAlign = "center";
158	    ctx.textBaseline = "middle";
159	    ctx.fillText("H", bx, by + 1);
160	
161	    // Smoke drifts with the wind; drawn smoothed.
162	    if (opts.showSmoke && !viewer) {
163	      const sctx = this.smokeLayer.getContext("2d")!;
164	      const simg = sctx.createImageData(w, h);
165	      const thick = world.cfg.thickSmoke;
166	      for (let i = 0; i < w * h; i++) {
167	        const a = Math.min(0.75, world.env.smoke[i] / (thick * 2.5));
168	        simg.data[i * 4] = 90;
169	        simg.data[i * 4 + 1] = 90;
170	        simg.data[i * 4 + 2] = 95;
171	        simg.data[i * 4 + 3] = a * 255;
172	      }
173	      sctx.putImageData(simg, 0, 0);
174	      ctx.imageSmoothingEnabled = true;
175	      ctx.drawImage(this.smokeLayer, 0, 0, w * s, h * s);
176	      ctx.imageSmoothingEnabled = false;
177	    }
178	
179	    // Comms blackout zones.
180	    ctx.setLineDash([6, 4]);
181	    ctx.lineWidth = 2;
182	    for (const b of world.blackouts) {
183	      ctx.strokeStyle = "#c77dff";
184	      ctx.fillStyle = "rgba(199,125,255,0.12)";
185	      ctx.beginPath();
186	      ctx.arc((b.x + 0.5) * s, (b.y + 0.5) * s, b.r * s, 0, Math.PI * 2);
187	      ctx.fill();
188	      ctx.stroke();
189	    }
190	    ctx.setLineDash([]);
191	
192	    // Comms links (who can talk to whom right now).
193	    if (opts.showLinks) {
194	      ctx.strokeStyle = "rgba(120,230,255,0.55)";
195	      ctx.lineWidth = 1;
196	      for (const [a, b] of world.network.links) {
197	        const pa = a === BASE_ID ? world.base : world.drones[a];
198	        const pb = b === BASE_ID ? world.base : world.drones[b];
199	        ctx.beginPath();
200	        ctx.moveTo((pa.x + 0.5) * s, (pa.y + 0.5) * s);
201	        ctx.lineTo((pb.x + 0.5) * s, (pb.y + 0.5) * s);
202	        ctx.stroke();
203	      }
204	    }
205	
206	    // Selected drone: sensor range, target, and its guesses about lost teammates.
207	    const sel = opts.selected !== null ? world.drones[opts.selected] : null;
208	    if (sel && sel.alive) {
209	      if (opts.showSensors) {
210	        ctx.strokeStyle = "rgba(255,255,255,0.5)";
211	        ctx.beginPath();
212	        ctx.arc((sel.x + 0.5) * s, (sel.y + 0.5) * s, world.cfg.sensorRadius * s, 0, Math.PI * 2);
213	        ctx.stroke();
214	      }
215	      if (opts.showClouds) {
216	        for (const [id, tr] of sel.trackers) {
217	          ctx.fillStyle = TEAM_COLOURS[id % TEAM_COLOURS.length];
218	          for (let k = 0; k < tr.n; k++) {
219	            ctx.globalAlpha = 0.55;
220	            ctx.fillRect((tr.xs[k] + 0.5) * s - 1.5, (tr.ys[k] + 0.5) * s - 1.5, 3, 3);
221	          }
222	          ctx.globalAlpha = 1;
223	        }
224	      }
225	    }
226	
227	    // Drones.
228	    for (const d of world.drones) this.drawDrone(ctx, d, d.id === opts.selected);
229	  }
230	
231	  private drawDrone(ctx: CanvasRenderingContext2D, d: Drone, selected: boolean) {
232	    const s = this.scale;
233	    const x = (d.x + 0.5) * s;
234	    const y = (d.y + 0.5) * s;
235	    if (!d.alive) {
236	      ctx.strokeStyle = "#ddd";
237	      ctx.lineWidth = 2;
238	      ctx.beginPath();
239	      ctx.moveTo(x - 4, y - 4);
240	      ctx.lineTo(x + 4, y + 4);
241	      ctx.moveTo(x + 4, y - 4);
242	      ctx.lineTo(x - 4, y + 4);
243	      ctx.stroke();
244	      return;
245	    }
246	    if (selected && d.state === "toFire") {
247	      ctx.strokeStyle = "rgba(255,159,28,0.8)";
248	      ctx.setLineDash([3, 3]);
249	      ctx.beginPath();
250	      ctx.moveTo(x, y);
251	      ctx.lineTo((d.targetX + 0.5) * s, (d.targetY + 0.5) * s);
252	      ctx.stroke();
253	      ctx.setLineDash([]);
254	    }
255	    const r = s * 0.75;
256	    ctx.fillStyle = STATE_COLOUR[d.state] ?? "#fff";
257	    ctx.strokeStyle = selected ? "#fff" : "#000";
258	    ctx.lineWidth = selected ? 2.5 : 1;
259	    ctx.beginPath();
260	    ctx.arc(x, y, r, 0, Math.PI * 2);
261	    ctx.fill();
262	    ctx.stroke();
263	    ctx.fillStyle = "#000";
264	    ctx.font = `bold ${Math.round(s * 0.9)}px sans-serif`;
265	    ctx.textAlign = "center";
266	    ctx.textBaseline = "middle";
267	    ctx.fillText(String(d.id), x, y + 1);
268	    // Water (blue) and battery (green) bars.
269	    const bw = s * 1.8;
270	    const cap = this.world.cfg.waterCapacity;
271	    ctx.fillStyle = "rgba(0,0,0,0.6)";
272	    ctx.fillRect(x - bw / 2, y - r - 7, bw, 6);
273	    ctx.fillStyle = "#4cc9f0";
274	    ctx.fillRect(x - bw / 2, y - r - 7, (bw * d.water) / cap, 3);
275	    ctx.fillStyle = d.damage > 0.5 ? "#ff595e" : "#80ed99";
276	    ctx.fillRect(x - bw / 2, y - r - 4, bw * Math.max(0, Math.min(d.battery, 1 - d.damage)), 3);
277	  }
278	
279	  // Which tile is under a canvas pixel?
280	  tileAt(px: number, py: number) {
281	    return { x: Math.floor(px / this.scale), y: Math.floor(py / this.scale) };
282	  }
283	}
