1	// Headless experiment runner: the same simulation code as the browser, no graphics.
2	// Runs every coordination mode over many seeds and comms conditions, then writes
3	//   results/runs.csv     one row per run
4	//   results/summary.csv  averages per condition
5	//   results/report.html  charts for the pitch
6	//
7	// Usage: npm run experiment -- [seeds=30]
8	import { mkdirSync, writeFileSync } from "node:fs";
9	import { Mode } from "../src/sim/config";
10	import { World } from "../src/sim/world";
11	
12	const SEEDS = Number(process.argv[2]) || 30;
13	const MODES: Mode[] = ["swarm", "central", "greedy"];
14	const RANGES = [6, 8, 11, 14, 20, 30, 200];
15	
16	interface Row {
17	  experiment: string;
18	  mode: string;
19	  commsRange: number;
20	  seed: number;
21	  burnt: number;
22	  villageLost: number;
23	  dronesLost: number;
24	  extinguishedAt: number;
25	  ticks: number;
26	}
27	
28	const rows: Row[] = [];
29	function run(experiment: string, mode: Mode | "none", seed: number, extra: Record<string, number | boolean>) {
30	  const w = new World({ seed, mode: mode === "none" ? "swarm" : mode, ...(mode === "none" ? { droneCount: 0 } : {}), ...extra });
31	  const m = w.runToEnd();
32	  rows.push({
33	    experiment,
34	    mode,
35	    commsRange: w.cfg.commsRange,
36	    seed,
37	    burnt: m.burnt,
38	    villageLost: m.villageLost ? 1 : 0,
39	    dronesLost: m.dronesLost,
40	    extinguishedAt: m.extinguishedAt,
41	    ticks: m.tick,
42	  });
43	}
44	
45	const t0 = Date.now();
46	// Experiment 1: how does each approach cope as comms get worse?
47	for (const range of RANGES) {
48	  for (const mode of MODES) {
49	    for (let s = 1; s <= SEEDS; s++) run("range", mode, s, { commsRange: range, baseCommsRange: Math.max(range, 12) * 1.4 });
50	  }
51	  process.stdout.write(`range ${range} done (${((Date.now() - t0) / 1000).toFixed(0)}s)\n`);
52	}
53	// Experiment 2: base goes offline shortly after the drones launch.
54	for (const mode of MODES) for (let s = 1; s <= SEEDS; s++) run("baseOutage", mode, s, { baseOutageAt: 120 });
55	// Reference: no drones at all.
56	for (let s = 1; s <= SEEDS; s++) run("noDrones", "none", s, {});
57	process.stdout.write(`all runs done (${((Date.now() - t0) / 1000).toFixed(0)}s)\n`);
58	
59	// ------------------------------------------------------------------ summarise
60	mkdirSync("results", { recursive: true });
61	const keys = Object.keys(rows[0]) as (keyof Row)[];
62	writeFileSync("results/runs.csv", [keys.join(","), ...rows.map((r) => keys.map((k) => r[k]).join(","))].join("\n"));
63	
64	interface Summary {
65	  experiment: string;
66	  mode: string;
67	  commsRange: number;
68	  n: number;
69	  burntMean: number;
70	  burntSe: number; // standard error of the mean
71	  villageLostRate: number;
72	  dronesLostMean: number;
73	}
74	const groups = new Map<string, Row[]>();
75	for (const r of rows) {
76	  const k = `${r.experiment}|${r.mode}|${r.commsRange}`;
77	  if (!groups.has(k)) groups.set(k, []);
78	  groups.get(k)!.push(r);
79	}
80	const summary: Summary[] = [];
81	for (const g of groups.values()) {
82	  const n = g.length;
83	  const mean = g.reduce((s, r) => s + r.burnt, 0) / n;
84	  const sd = Math.sqrt(g.reduce((s, r) => s + (r.burnt - mean) ** 2, 0) / Math.max(1, n - 1));
85	  summary.push({
86	    experiment: g[0].experiment,
87	    mode: g[0].mode,
88	    commsRange: g[0].commsRange,
89	    n,
90	    burntMean: mean,
91	    burntSe: sd / Math.sqrt(n),
92	    villageLostRate: g.reduce((s, r) => s + r.villageLost, 0) / n,
93	    dronesLostMean: g.reduce((s, r) => s + r.dronesLost, 0) / n,
94	  });
95	}
96	const skeys = Object.keys(summary[0]) as (keyof Summary)[];
97	writeFileSync(
98	  "results/summary.csv",
99	  [skeys.join(","), ...summary.map((r) => skeys.map((k) => (typeof r[k] === "number" ? +(r[k] as number).toFixed(3) : r[k])).join(","))].join("\n"),
100	);
101	
102	console.log("\nComms range sweep (mean tiles burnt ± SE, village lost %):");
103	for (const range of RANGES) {
104	  const line = MODES.map((m) => {
105	    const s = summary.find((x) => x.experiment === "range" && x.mode === m && x.commsRange === range)!;
106	    return `${m}: ${s.burntMean.toFixed(0)}±${s.burntSe.toFixed(0)} (${(s.villageLostRate * 100).toFixed(0)}%)`;
107	  });
108	  console.log(`range ${String(range).padStart(3)} | ${line.join(" | ")}`);
109	}
110	console.log("\nBase outage at tick 120:");
111	for (const m of MODES) {
112	  const s = summary.find((x) => x.experiment === "baseOutage" && x.mode === m)!;
113	  console.log(`  ${m}: ${s.burntMean.toFixed(0)}±${s.burntSe.toFixed(0)} burnt, village lost ${(s.villageLostRate * 100).toFixed(0)}%`);
114	}
115	const nd = summary.find((x) => x.experiment === "noDrones")!;
116	console.log(`No drones: ${nd.burntMean.toFixed(0)} burnt, village lost ${(nd.villageLostRate * 100).toFixed(0)}%`);
117	
118	// ------------------------------------------------------------------ HTML report
119	const COLOURS: Record<string, string> = { swarm: "#ff9f1c", central: "#4cc9f0", greedy: "#b388ff", none: "#9aa0a6" };
120	const LABELS: Record<string, string> = { swarm: "Swarm (ours)", central: "Central control", greedy: "No coordination", none: "No drones" };
121	
122	function lineChart(metric: "burntMean" | "villageLostRate", title: string, yLabel: string, yMax: number) {
123	  const W = 640;
124	  const H = 320;
125	  const L = 60;
126	  const B = 44;
127	  const T = 30;
128	  const R = 150;
129	  const xs = RANGES.map((_, i) => L + (i * (W - L - R)) / (RANGES.length - 1));
130	  const y = (v: number) => T + (H - T - B) * (1 - v / yMax);
131	  let svg = `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg" font-family="system-ui,sans-serif" font-size="12">`;
132	  svg += `<text x="${L}" y="18" font-size="14" font-weight="600" fill="#e8e6e3">${title}</text>`;
133	  for (let k = 0; k <= 4; k++) {
134	    const v = (yMax * k) / 4;
135	    svg += `<line x1="${L}" x2="${W - R}" y1="${y(v)}" y2="${y(v)}" stroke="#2c313a"/>`;
136	    svg += `<text x="${L - 8}" y="${y(v) + 4}" text-anchor="end" fill="#9aa0a6">${metric === "villageLostRate" ? Math.round(v * 100) + "%" : Math.round(v)}</text>`;
137	  }
138	  RANGES.forEach((r, i) => (svg += `<text x="${xs[i]}" y="${H - B + 18}" text-anchor="middle" fill="#9aa0a6">${r === 200 ? "∞" : r}</text>`));
139	  svg += `<text x="${(L + W - R) / 2}" y="${H - 6}" text-anchor="middle" fill="#9aa0a6">comms range (tiles) — worse comms on the left</text>`;
140	  svg += `<text transform="translate(14 ${(T + H - B) / 2}) rotate(-90)" text-anchor="middle" fill="#9aa0a6">${yLabel}</text>`;
141	  MODES.forEach((m, mi) => {
142	    const pts = RANGES.map((r) => summary.find((x) => x.experiment === "range" && x.mode === m && x.commsRange === r)!);
143	    if (metric === "burntMean") {
144	      pts.forEach((p, i) => {
