// Screenshot helper: node shot.mjs <url> <out.png> [waitMs] [width] [height] [jsToEval]
// Prints console errors / page errors so broken pages are obvious.
import { chromium } from "playwright";

const [url, out, waitMs = "1500", width = "1440", height = "900", js = ""] = process.argv.slice(2);
const browser = await chromium.launch({
  args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"],
});
const page = await browser.newPage({ viewport: { width: +width, height: +height }, deviceScaleFactor: 1 });
const errors = [];
page.on("console", (m) => {
  if (m.type() === "error" || m.type() === "warning") errors.push(`[console.${m.type()}] ${m.text()}`);
});
page.on("pageerror", (e) => errors.push(`[pageerror] ${e.message}\n${e.stack ?? ""}`));
page.on("requestfailed", (r) => errors.push(`[requestfailed] ${r.url()} ${r.failure()?.errorText}`));
await page.goto(url, { waitUntil: "load" });
await page.waitForTimeout(+waitMs);
if (js) {
  const result = await page.evaluate(js);
  if (result !== undefined) console.log("eval:", typeof result === "string" ? result : JSON.stringify(result));
  await page.waitForTimeout(400);
}
await page.screenshot({ path: out });
console.log(errors.length ? errors.join("\n") : "no console errors");
await browser.close();

